style.css:
/* Heavenly Monochrome — Roblox */
:root {
  /* Swap these colors to customize your theme */
  --my-black: #101014;
  --my-dark: #191920;
  --my-white: #f8f7fc;
  --my-silver: #c9c8d4;
  --my-glow: rgba(235, 232, 255, 0.2);
}

/* dreamy monochrome background */
html,
body {
  background: #101014 !important;
  color: var(--my-white) !important;
  font-family: "Georgia", "Times New Roman", serif !important;
}

/* elegant links */
a {
  color: var(--my-silver) !important;
  transition: color 0.2s ease, text-shadow 0.2s ease !important;
}

a:hover {
  color: #ffffff !important;
  text-shadow: 0 0 12px var(--my-glow) !important;
}

/* soft image styling */
img {
  border-radius: 12px !important;
}

/* monochrome selection */
::selection {
  background: #dedbe9 !important;
  color: #111116 !important;
}

/* subtle scrollbar */
::-webkit-scrollbar {
  width: 9px !important;
}

::-webkit-scrollbar-track {
  background: #111116 !important;
}

::-webkit-scrollbar-thumb {
  background: #777582 !important;
  border-radius: 20px !important;
}
